import { initSlider } from '@/js/base/init-circle.js';

export function circleProgress () {
  const sliderWrapper = document.querySelector('.screen5__circle-container');
  const progressBar = document.querySelector('.screen5__slider-progress');
  const buttons = document.querySelectorAll('.screen5__circle-dot');
  const svgElement = document.querySelector('.screen5__circle-svg');
  const circleTrack = document.querySelector('.screen5__slider-track');
  const position = document.querySelector('.screen5__circle-position');
  const stages = document.querySelectorAll('.screen5__stage');

  let svgCentre;
  let svgRadius;
  let circumference;
  const strokeWidth = 2
  let angles = [];

  function setupCircle () {
    const values = initSlider(sliderWrapper, svgElement, circleTrack, progressBar, strokeWidth)
    svgCentre = values.svgCentre;
    svgRadius = values.svgRadius;
    circumference = values.circumference;
  }

  function updateButtons () {
    angles = [...buttons].map((_, i) =>
      (i / buttons.length) * 2 * Math.PI - Math.PI / 2);

    buttons.forEach((button, index) => {
      const x = svgCentre + svgRadius * Math.cos(angles[index]);
      const y = svgCentre + svgRadius * Math.sin(angles[index])
      button.style.left = `${x}px`;
      button.style.top = `${y}px`;
    })
  }

  function attachButtonEvents () {
    buttons.forEach((button, index) => {
      button.addEventListener('click', (e) => {
        buttons.forEach((button, i) => {
          button.classList.remove('active', 'completed');
          if (i < index) {
            button.classList.add('completed');
          }
        });

        setTimeout(( ) =>{
          button.classList.add('active');
        }, 400)
        position.textContent = `${index + 1}`

        stages.forEach((stage) => {
          stage.classList.remove('active');
        })
        stages[index].classList.add('active');

        if (index === 0) {
          progressBar.style.strokeDashoffset = `${circumference}`;
        } else {
          const deltaAngle = angles[index] - angles[0];
          const progress = (deltaAngle / (2 * Math.PI)) * circumference;
          progressBar.style.strokeDashoffset = `${circumference - progress}`;
        }
      })
    })
  }

  function initSection () {
    buttons[0].classList.add('active');
    stages[0].classList.add('active');
    position.textContent = `1`
  }

  let resizeTimer;
  let lastCircleSize = sliderWrapper.offsetHeight;

  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      const newSize = sliderWrapper.offsetHeight;

      if (newSize === lastCircleSize) return;
      lastCircleSize = newSize;
      setupCircle()
      updateButtons();

      buttons.forEach((button) => {
        button.classList.remove('active', 'completed');
      })
      stages.forEach((stage) => {
        stage.classList.remove('active');
      })
      initSection()
    }, 150)
  });

  setTimeout(() => {
    setupCircle()
    updateButtons();
    attachButtonEvents();
    initSection()
  }, 200)
}